import { Injectable } from '@angular/core'
import { Router, CanActivate, ActivatedRouteSnapshot } from '@angular/router'

@Injectable()
export class TenantGuardService implements CanActivate {
    canActivate(): boolean {
        const domain = window.location.host
        let tenant = domain.split('.')[0].replace('-', '')
        
        if (
            tenant != 'demo' &&
            tenant != 'angelesbilbao6' &&
            tenant != 'divinaprovidencia' &&
            tenant != 'guadalupevolcanes' &&
            tenant != 'canoa' &&
            tenant != 'santuariomisericordia' &&
            tenant != 'santuarioguadalupano_' &&
            tenant != 'localhost:4200'
        ) {
            //this.router.navigate(['ingresos'])
            return false
        }
        return true
    }
}
