class CalendarEventModel implements CalendarEvent {
    id?: string | number | undefined
    start: Date
    end?: Date | undefined
    title: string
    color?: EventColor | undefined
    actions?: CalendarEventAction[] | undefined
    allDay?: boolean | undefined
    cssClass?: string | undefined
    resizable?:
        | { beforeStart?: boolean | undefined; afterEnd?: boolean | undefined }
        | undefined
    draggable?: boolean | undefined
    meta?: any
    restricted: boolean
    constructor(
        id: number,
        startDate: Date,
        startTime: string,
        endDate: Date,
        endTime: string,
        title: string,
        color: EventColor,
        restricted: boolean
    ) {
        this.id = id
        this.start = DateUtil.AddTimeToDate(startDate, startTime)
        this.end = DateUtil.AddTimeToDate(endDate, endTime)
        this.color = color
        this.title = title
        this.restricted = restricted
    }
    
}
