import {
    ChangeDetectorRef,
    Component,
    OnInit,
    ViewEncapsulation,
} from '@angular/core'
import { LoadingService } from './core/services/util/loading.service'
import { ConfigurationService } from './core/services/api/configuration.service'
import { ConfigurationItem } from './core/interfaces/configuration-item'

@Component({
    selector: 'app-root',
    templateUrl: './app.component.html',
    styleUrls: ['./app.component.scss'],
})
export class AppComponent implements OnInit {
    items: ConfigurationItem[]
    title = 'ecclesia-frontend'
    private _loading = false
    private _date = new Date()
    get loading() {
        return this._loading
    }
    get date() {
        return this._date
    }

    constructor(
        private loadingService: LoadingService,
        private configurationService: ConfigurationService,
        private changeDetRef: ChangeDetectorRef
    ) {
        this.items = []
    }
    ngOnInit(): void {
        this.loadingService.loading.subscribe((loading) => {
            this._loading = loading
            this.changeDetRef.detectChanges()
        })

        this.configurationService.retrieve().subscribe(items => {
            this.items = items
        })

       // console.log(this.items);
    }
}
